def rect_rule2(t, maxgap=6, MK=9, FILL=2, minside=2, fillcorner=True):
    H,W=len(t),len(t[0])
    marks=[(i,j) for i in range(H) for j in range(W) if t[i][j]==MK]
    ms=set(marks)
    rows=sorted({i for i,j in marks}); cols=sorted({j for i,j in marks})
    g=[r[:] for r in t]
    for r1 in rows:
        for r2 in rows:
            if r2<=r1: continue
            for c1 in cols:
                for c2 in cols:
                    if c2<=c1: continue
                    corners=[(r1,c1),(r1,c2),(r2,c1),(r2,c2)]
                    ncorner=sum(1 for c in corners if c in ms)
                    if ncorner<3: continue
                    # side mark counts within bbox
                    def sm_top(): return sum(1 for (i,j) in ms if i==r1 and c1<=j<=c2)
                    def sm_bot(): return sum(1 for (i,j) in ms if i==r2 and c1<=j<=c2)
                    def sm_l():   return sum(1 for (i,j) in ms if j==c1 and r1<=i<=r2)
                    def sm_r():   return sum(1 for (i,j) in ms if j==c2 and r1<=i<=r2)
                    if min(sm_top(),sm_bot(),sm_l(),sm_r())<minside: continue
                    for r,c,endpoints,horiz in [(r1,None,(c1,c2),True),(r2,None,(c1,c2),True),
                                                (None,c1,(r1,r2),False),(None,c2,(r1,r2),False)]:
                        if horiz:
                            pos=sorted({j for (i,j) in ms if i==r and c1<=j<=c2})
                        else:
                            pos=sorted({i for (i,j) in ms if j==c and r1<=i<=r2})
                        allp=sorted(set(pos)|set(endpoints))
                        for a,b in zip(allp,allp[1:]):
                            if b-a-1<=maxgap:
                                for x in range(a+1,b):
                                    if horiz: g[r][x]=FILL
                                    else: g[x][c]=FILL
                    if fillcorner:
                        for (i,j) in corners:
                            if (i,j) not in ms: g[i][j]=FILL
    return g

