def chains(line_marks, G):
    # line_marks: sorted positions along a line; group into chains where consecutive gap<=G+1
    chs=[]; cur=[line_marks[0]]
    for p in line_marks[1:]:
        if p-cur[-1]<=G+1: cur.append(p)
        else: chs.append(cur); cur=[p]
    chs.append(cur)
    return chs

def chain_rule(t, bg, MK, G=2, tailgap=2, fill_junction=True):
    H,W=len(t),len(t[0])
    marks={(i,j) for i in range(H) for j in range(W) if t[i][j]==MK}
    fills=set()
    def rowmarks(i): return sorted(j for (a,j) in marks if a==i)
    def colmarks(j): return sorted(i for (i,a) in marks if a==j)
    # 1) gap fills within chains
    for i in range(H):
        rm=rowmarks(i)
        if len(rm)<2: continue
        for ch in chains(rm,G):
            for a,b in zip(ch,ch[1:]):
                fills|={(i,k) for k in range(a+1,b)}
    for j in range(W):
        cm=colmarks(j)
        if len(cm)<2: continue
        for ch in chains(cm,G):
            for a,b in zip(ch,ch[1:]):
                fills|={(k,j) for k in range(a+1,b)}
    filled=marks|fills
    # 2) dangling ends extend to nearest perpendicular line
    def perp_exists(i,j,horiz):
        # is there a mark on row i (if horiz) at column j? i.e., cell itself on perpendicular line
        return (i,j) in marks
    for (i,j) in list(marks):
        rm=rowmarks(i); cm=colmarks(j)
        # vertical dangling: top end of a vertical chain
        for ch in chains(cm,G) if len(cm)>=2 else []:
            for end,dirn in ((ch[0],-1),(ch[-1],1)):
                if (i,j)!=end: continue
                # walk in dirn, fill bg cells up to tailgap, plus junction on next row with perpendicular line
                for d in range(1,tailgap+2):
                    ni=i+dirn*d
                    if not(0<=ni<H): break
                    if (ni,j) in marks: break
                    if (ni,j) in fills: break
                    # junction check: does row ni have a line crossing col j?
                    # perpendicular line = row ni contains marks; junction adjacent to a mark?
                    if d<=tailgap:
                        fills.add((ni,j)); filled.add((ni,j))
                    else:
                        # junction cell: fill if adjacent (in row ni) to a mark/filled
                        if fill_junction and ((ni,j-1) in filled or (ni,j+1) in filled or (ni-1,j) in filled or (ni+1,j) in filled):
                            fills.add((ni,j))
                        break
    # horizontal dangling ends
    for (i,j) in list(marks):
        rm=rowmarks(i)
        if len(rm)<2: continue
        for ch in chains(rm,G):
            for end,dirn in ((ch[0],-1),(ch[-1],1)):
                if (i,j)!=end: continue
                for d in range(1,tailgap+2):
                    nj=j+dirn*d
                    if not(0<=nj<W): break
                    if (i,nj) in marks: break
                    if (i,nj) in fills: break
                    if d<=tailgap:
                        fills.add((i,nj)); filled.add((i,nj))
                    else:
                        if fill_junction and ((i-1,nj) in filled or (i+1,nj) in filled or (i,nj-1) in filled or (i,nj+1) in filled):
                            fills.add((i,nj))
                        break
    g=[r[:] for r in t]
    for (i,j) in fills: g[i][j]=2
    return g,fills

