def solve_chain_rect(t, MK, G=2, tailgap=2, verbose=False):
    H,W=len(t),len(t[0])
    marks={(i,j) for i in range(H) for j in range(W) if t[i][j]==MK}
    fills=set(); filled=set(marks)
    rowm={i:sorted(j for (a,j) in marks if a==i) for i in range(H)}
    colm={j:sorted(i for (i,a) in marks if a==j) for j in range(W)}
    def side_ok(cells, c_a, c_b):
        # cells: list of positions along side between corners c_a..c_b (inclusive coords);
        # chain-connected allowing gaps<=G, endpoints within tailgap+1 of corners
        if not cells: return False
        chs=chains(cells,G)
        return chs[0][0]<=c_a+tailgap+1 and chs[-1][-1]>=c_b-tailgap-1
    rects=[]
    rows_with=sorted(rowm.keys())
    for r1 in rows_with:
        for r2 in rows_with:
            if r2<r1+2: continue
        pass
    # candidate rectangles: corners marked subset
    mr=sorted(set(i for i,j in marks)); mc=sorted(set(j for i,j in marks))
    for r1 in mr:
        for r2 in mr:
            if r2<r1+2: continue
            for c1 in mc:
                for c2 in mc:
                    if c2<c1+2: continue
                    corners=[(r1,c1),(r1,c2),(r2,c1),(r2,c2)]
                    n=sum(1 for c in corners if c in marks)
                    if n<3: continue
                    top=[j for j in rowm.get(r1,[]) if c1<=j<=c2]
                    bot=[j for j in rowm.get(r2,[]) if c1<=j<=c2]
                    lef=[i for i in colm.get(c1,[]) if r1<=i<=r2]
                    rig=[i for i in colm.get(c2,[]) if r1<=i<=r2]
                    if side_ok(top,c1,c2) and side_ok(bot,c1,c2) and side_ok(lef,r1,r2) and side_ok(rig,r1,r2):
                        rects.append((r1,r2,c1,c2,n))
    # keep maximal rectangles (not contained in another)
    rects=[R for R in rects if not any(R!=S and R[0]>=S[0] and R[1]<=S[1] and R[2]>=S[2] and R[3]<=S[3] for S in rects)]
    if verbose: print('rects:',rects)
    for (r1,r2,c1,c2,n) in rects:
        for j in range(c1,c2+1):
            for i in (r1,r2):
                if (i,j) not in filled: fills.add((i,j)); filled.add((i,j))
        for i in range(r1,r2+1):
            for j in (c1,c2):
                if (i,j) not in filled: fills.add((i,j)); filled.add((i,j))
    # 2) chain gaps (both orientations), skip cells already filled
    for i in range(H):
        for ch in chains(rowm.get(i,[]),G):
            for a,b in zip(ch,ch[1:]):
                for k in range(a+1,b):
                    if (i,k) not in filled: fills.add((i,k)); filled.add((i,k))
    for j in range(W):
        for ch in chains(colm.get(j,[]),G):
            for a,b in zip(ch,ch[1:]):
                for k in range(a+1,b):
                    if (k,j) not in filled: fills.add((k,j)); filled.add((k,j))
    # 3) tails: dangling chain ends
    def try_tail(start, dirn, axis, fixed):
        # axis 0: vertical (move rows), fixed=col ; axis 1: horizontal
        d=0
        for d in range(1,tailgap+2):
            if axis==0: cell=(start+dirn*d, fixed)
            else: cell=(fixed, start+dirn*d)
            if not(0<=cell[0]<H and 0<=cell[1]<W): return
            if cell in marks or cell in fills: return
            if d<=tailgap:
                fills.add(cell); filled.add(cell)
            else:
                # junction: fill if adjacent (perpendicular-ish) to mark/filled
                i,j=cell
                adj=[(i-1,j),(i+1,j),(i,j-1),(i,j+1)]
                if any(a in filled for a in adj):
                    fills.add(cell)
                return
    for j in range(W):
        for ch in chains(colm.get(j,[]),G):
            if len(ch)<2: continue
            try_tail(ch[0],-1,0,j); try_tail(ch[-1],1,0,j)
    for i in range(H):
        for ch in chains(rowm.get(i,[]),G):
            if len(ch)<2: continue
            try_tail(ch[0],-1,1,i); try_tail(ch[-1],1,1,i)
    g=[r[:] for r in t]
    for (i,j) in fills: g[i][j]=2
    return g,fills,rects

