def solve_final(t, MK, G=2, reach=3):
    H,W=len(t),len(t[0])
    marks={(i,j) for i in range(H) for j in range(W) if t[i][j]==MK}
    rowm={i:sorted(j for (a,j) in marks if a==i) for i in range(H)}
    colm={j:sorted(i for (i,a) in marks if a==j) for j in range(W)}
    fills=set(); filled=set(marks)
    def add(c): fills.add(c); filled.add(c)
    # --- maximal rectangles ---
    mr=sorted({i for i,j in marks}); mc=sorted({j for i,j in marks})
    def chains(line,G=G):
        if not line: return []
        chs=[]; cur=[line[0]]
        for p in line[1:]:
            if p-cur[-1]<=G+1: cur.append(p)
            else: chs.append(cur); cur=[p]
        chs.append(cur); return chs
    def side_reach(cells, a, b):
        return bool(cells) and cells[0]<=a+reach and cells[-1]>=b-reach
    rects=[]
    for r1 in mr:
        for r2 in mr:
            if r2<r1+2: continue
            for c1 in mc:
                for c2 in mc:
                    if c2<c1+2: continue
                    cs=[(r1,c1),(r1,c2),(r2,c1),(r2,c2)]
                    if sum(1 for c in cs if c in marks)<3: continue
                    top=[j for j in rowm.get(r1,[]) if c1<=j<=c2]
                    bot=[j for j in rowm.get(r2,[]) if c1<=j<=c2]
                    lef=[i for i in colm.get(c1,[]) if r1<=i<=r2]
                    rig=[i for i in colm.get(c2,[]) if r1<=i<=r2]
                    if side_reach(top,c1,c2) and side_reach(bot,c1,c2) and side_reach(lef,r1,r2) and side_reach(rig,r1,r2):
                        rects.append((r1,r2,c1,c2))
    rects=[R for R in rects if not any(R!=S and R[0]>=S[0] and R[1]<=S[1] and R[2]>=S[2] and R[3]<=S[3] for S in rects)]
    for (r1,r2,c1,c2) in rects:
        for j in range(c1,c2+1):
            for i in (r1,r2):
                if (i,j) not in filled: add((i,j))
        for i in range(r1,r2+1):
            for j in (c1,c2):
                if (i,j) not in filled: add((i,j))
        # thick sides: adjacent row/col with >=2 marks near both corners
        for rr in (r1-1,r1+1,r2-1,r2+1):
            if 0<=rr<H and rr not in (r1,r2):
                ln=[j for j in rowm.get(rr,[]) if c1<=j<=c2]
                if len(ln)>=2 and ln[0]<=c1+reach and ln[-1]>=c2-reach:
                    for j in range(c1,c2+1):
                        if (rr,j) not in filled: add((rr,j))
        for cc in (c1-1,c1+1,c2-1,c2+1):
            if 0<=cc<W and cc not in (c1,c2):
                ln=[i for i in colm.get(cc,[]) if r1<=i<=r2]
                if len(ln)>=2 and ln[0]<=r1+reach and ln[-1]>=r2-reach:
                    for i in range(r1,r2+1):
                        if (i,cc) not in filled: add((i,cc))
    # --- chain gaps ---
    for i in range(H):
        for ch in chains(rowm.get(i,[])):
            for a,b in zip(ch,ch[1:]):
                for k in range(a+1,b):
                    if (i,k) not in filled: add((i,k))
    for j in range(W):
        for ch in chains(colm.get(j,[])):
            for a,b in zip(ch,ch[1:]):
                for k in range(a+1,b):
                    if (k,j) not in filled: add((k,j))
    # --- tails ---
    def tail(start, dirn, axis, fixed):
        path=[]
        for d in range(1,reach+1):
            cell=(start+dirn*d,fixed) if axis==0 else (fixed,start+dirn*d)
            if not(0<=cell[0]<H and 0<=cell[1]<W): return []
            if cell in marks: return path+[cell] if path else []
            if cell in fills or cell in filled and cell not in marks: return path if path else []
            path.append(cell)
            i,j=cell
            if axis==0: perp=[(i,j-1),(i,j+1)]
            else: perp=[(i-1,j),(i+1,j)]
            if any(p in filled or p in marks for p in perp):
                return path+[cell]  # junction included
        # mutual meeting fallback
        return ('PATH',path)
    tails=[]
    for j in range(W):
        for ch in chains(colm.get(j,[])):
            if len(ch)<2: continue
            tails.append((ch[0],-1,0,j)); tails.append((ch[-1],1,0,j))
    for i in range(H):
        for ch in chains(rowm.get(i,[])):
            if len(ch)<2: continue
            tails.append((ch[0],-1,1,i)); tails.append((ch[-1],1,1,i))
    paths={}
    for idx,(start,dirn,axis,fixed) in enumerate(tails):
        res=tail(start,dirn,axis,fixed)
        if isinstance(res,tuple): paths[idx]=res[1]
        elif res:
            for c in res: 
                if c not in filled: add(c)
    # mutual meeting: junction of one equals a cell in another's path (perpendicular axes)
    for idx,p in paths.items():
        start,dirn,axis,fixed=tails[idx]
        junction=p[-1]
        for idx2,q in paths.items():
            if idx2==idx or tails[idx2][2]==axis: continue
            if junction in q:
                for c in p:
                    if c not in filled: add(c)
                break
    g=[r[:] for r in t]
    for (i,j) in fills: g[i][j]=2
    return g,fills,rects

