def solve_v6(t, MK, G=2, reach=3, minmarks=4, gapmax=2):
    H,W=len(t),len(t[0])
    marks={(i,j) for i in range(H) for j in range(W) if t[i][j]==MK}
    filled=set(marks); fills=set()
    def add(c): fills.add(c); filled.add(c)
    def chains(line):
        if not line: return []
        chs=[]; cur=[line[0]]
        for p in line[1:]:
            if p-cur[-1]<=G+1: cur.append(p)
            else: chs.append(cur); cur=[p]
        chs.append(cur); return chs
    def side_reach(cells,a,b): return bool(cells) and cells[0]<=a+reach and cells[-1]>=b-reach
    mr=sorted({i for i,j in marks}); mc=sorted({j for i,j in marks})
    rects=[]
    for r1 in mr:
        for r2 in mr:
            if r2<r1+2: continue
            for c1 in mc:
                for c2 in mc:
                    if c2<c1+2: continue
                    if sum(1 for c in [(r1,c1),(r1,c2),(r2,c1),(r2,c2)] if c in marks)<3: continue
                    if (side_reach([j for j in range(c1,c2+1) if (r1,j) in marks],c1,c2)
                        and side_reach([j for j in range(c1,c2+1) if (r2,j) in marks],c1,c2)
                        and side_reach([i for i in range(r1,r2+1) if (i,c1) in marks],r1,r2)
                        and side_reach([i for i in range(r1,r2+1) if (i,c2) in marks],r1,r2)):
                        rects.append((r1,r2,c1,c2))
    rects=[R for R in rects if not any(R!=S and R[0]>=S[0] and R[1]<=S[1] and R[2]>=S[2] and R[3]<=S[3] for S in rects)]
    side_cells=set()
    for (r1,r2,c1,c2) in rects:
        for j in range(c1,c2+1): side_cells.add((r1,j)); side_cells.add((r2,j))
        for i in range(r1,r2+1): side_cells.add((i,c1)); side_cells.add((i,c2))
    for c in side_cells:
        if c not in filled: add(c)
    # tight 2-thick bottom band: rows r2-1,r2, cols c1+1..c2, 4 corners marked
    for (r1,r2,c1,c2) in rects:
        if all(q in marks for q in [(r2-1,c1+1),(r2-1,c2),(r2,c1+1),(r2,c2)]):
            for j in range(c1+1,c2+1):
                for i in (r2-1,r2):
                    if (i,j) not in filled: add((i,j))
    rowm={i:sorted(j for (a,j) in marks if a==i) for i in range(H)}
    colm={j:sorted(i for (i,a) in marks if a==j) for j in range(W)}
    for i in range(H):
        rm=rowm[i]
        if len(rm)>=minmarks:
            for a,b in zip(rm,rm[1:]):
                if b-a-1<=gapmax:
                    for k in range(a+1,b):
                        if (i,k) not in filled: add((i,k))
    for j in range(W):
        cm=colm[j]
        if len(cm)>=minmarks:
            for a,b in zip(cm,cm[1:]):
                if b-a-1<=gapmax:
                    for k in range(a+1,b):
                        if (k,j) not in filled: add((k,j))
    def good_junction(i,j,axis):
        line = rowm.get(i,[]) if axis==0 else colm.get(j,[])
        if axis==0:
            return any(len(ch)>=2 and j in (ch[0]-1,ch[0]+1,ch[-1]-1,ch[-1]+1) for ch in chains(line))
        return any(len(ch)>=2 and i in (ch[0]-1,ch[0]+1,ch[-1]-1,ch[-1]+1) for ch in chains(line))
    def tail(start,dirn,axis,fixed):
        path=[]
        for d in range(1,reach+1):
            cell=(start+dirn*d,fixed) if axis==0 else (fixed,start+dirn*d)
            if not(0<=cell[0]<H and 0<=cell[1]<W): return []
            if cell in marks or cell in filled: return path if path else []
            path.append(cell)
            i,j=cell
            if good_junction(i,j,axis): return path+[cell]
        return ('PATH',path)
    tails=[]
    for j in range(W):
        for ch in chains(colm.get(j,[])):
            if len(ch)<2: continue
            tails.append((ch[0],-1,0,j)); tails.append((ch[-1],1,0,j))
    for i in range(H):
        for ch in chains(rowm.get(i,[])):
            if len(ch)<2: continue
            tails.append((ch[0],-1,1,i)); tails.append((ch[-1],1,1,i))
    paths={}
    for idx,(start,dirn,axis,fixed) in enumerate(tails):
        res=tail(start,dirn,axis,fixed)
        if isinstance(res,tuple): paths[idx]=res[1]
        elif res:
            for c in res:
                if c not in filled: add(c)
    for idx,p in paths.items():
        junction=p[-1]
        for idx2,q in paths.items():
            if idx2==idx or tails[idx2][2]==tails[idx][2]: continue
            if junction in q:
                for c in p:
                    if c not in filled: add(c)
                break
    g=[r[:] for r in t]
    for (i,j) in fills: g[i][j]=2
    return g,fills,rects

